/* Diagnostic EP0 fallback, no interface claim or device seizure.
 * Build: clang -framework IOKit -framework CoreFoundation iokit-request.c -o iokit-request
 * Arguments are generated by usb-command.ts, not an interactive command API.
 */
#include <CoreFoundation/CoreFoundation.h>
#include <IOKit/IOCFPlugIn.h>
#include <IOKit/usb/IOUSBLib.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
  if (argc != 10) return 2;
  unsigned long number[7];
  for (int i = 0; i < 7; i++) {
    char *end;
    number[i] = strtoul(argv[i + 1], &end, 10);
    if (*end || !*argv[i + 1] || number[i] > 65535) return 2;
  }
  if (number[3] > 255 || number[4] > 255) return 2;
  char *bus_end;
  unsigned long bus = strtoul(argv[9], &bus_end, 10);
  if (*bus_end || !*argv[9] || bus > 255) return 2;
  UInt8 bytes[256] = {0};
  UInt16 length;
  if (number[3] & 0x80) {
    char *end;
    unsigned long n = strtoul(argv[8], &end, 10);
    if (*end || n > sizeof(bytes)) return 2;
    length = (UInt16)n;
  } else {
    size_t n = strlen(argv[8]);
    if (n % 2 || n / 2 > sizeof(bytes)) return 2;
    length = (UInt16)(n / 2);
    for (int i = 0; i < length; i++) {
      char pair[3] = {argv[8][2*i], argv[8][2*i+1], 0}, *end;
      bytes[i] = (UInt8)strtoul(pair, &end, 16);
      if (*end) return 2;
    }
  }
  io_iterator_t iterator;
  if (IOServiceGetMatchingServices(kIOMainPortDefault, IOServiceMatching(kIOUSBDeviceClassName), &iterator)) return 1;
  io_service_t service;
  int result = 1;
  while ((service = IOIteratorNext(iterator))) {
    IOCFPlugInInterface **plugin = NULL;
    IOUSBDeviceInterface **device = NULL;
    SInt32 score;
    IOReturn status = IOCreatePlugInInterfaceForService(service, kIOUSBDeviceUserClientTypeID,
      kIOCFPlugInInterfaceID, &plugin, &score);
    IOObjectRelease(service);
    if (status || !plugin) continue;
    HRESULT query = (*plugin)->QueryInterface(plugin, CFUUIDGetUUIDBytes(kIOUSBDeviceInterfaceID), (LPVOID *)&device);
    (*plugin)->Release(plugin);
    if (query || !device) continue;
    UInt16 vendor = 0, product = 0;
    USBDeviceAddress address = 0;
    UInt32 location = 0;
    (*device)->GetDeviceVendor(device, &vendor);
    (*device)->GetDeviceProduct(device, &product);
    (*device)->GetDeviceAddress(device, &address);
    (*device)->GetLocationID(device, &location);
    if (vendor != number[0] || product != number[1] || address != number[2] || (location >> 24) != bus) {
      (*device)->Release(device); continue;
    }
    status = (*device)->USBDeviceOpen(device);
    if (!status) {
      IOUSBDevRequest request = {0};
      request.bmRequestType = (UInt8)number[3]; request.bRequest = (UInt8)number[4];
      request.wValue = (UInt16)number[5]; request.wIndex = (UInt16)number[6];
      request.wLength = length; request.pData = bytes;
      status = (*device)->DeviceRequest(device, &request);
      if (!status && (number[3] & 0x80)) {
        for (UInt32 i = 0; i < request.wLenDone; i++) printf("%02x", bytes[i]);
      }
      (*device)->USBDeviceClose(device);
    }
    if (status) fprintf(stderr, "IOKit request failed: 0x%08x\n", status);
    else result = 0;
    (*device)->Release(device);
    break;
  }
  IOObjectRelease(iterator);
  if (result) fprintf(stderr, "IOKit device not found or request failed\n");
  return result;
}
